    /**
     * Tests that the method correctly wraps a standard Exception into a JsonMappingException
     * by extracting the root cause message.
     */
    @Test
    public void test_throwAsIOE_wrapsExceptionWithRootCauseMessage() throws Exception {
        // Arrange
        RuntimeException rootCause = new RuntimeException("root cause message");
        Exception wrappedException = new Exception("wrapper", rootCause);

        // Act & Assert
        try {
            // Accessing protected method via a helper or reflection if necessary, 
            // but here we use the subclass in the same package.
            sut.invokeThrowAsIOE(mockParser, wrappedException);
            Assert.fail("Expected JsonMappingException to be thrown");
        } catch (Exception e) {
            // Since we are calling a method that throws IOException, and it's wrapped in a 
            // wrapper in some test setups, we check the cause.
            // In this specific test, the method itself throws JsonMappingException.
            Throwable actualException = e;
            if (e instanceof java.lang.reflect.InvocationTargetException) {
                actualException = e.getCause();
            }

            assertTrue("Exception should be JsonMappingException", actualException instanceof JsonMappingException);
            assertEquals("root cause message", actualException.getMessage());
            assertEquals(rootCause, actualException.getCause());
        }
    }

    /**
     * Tests that if the exception is already an IOException, ClassUtil.throwIfIOE 
     * (implied logic) allows it or handles it. 
     * Note: Based on the code provided, if e is IOException, it proceeds to wrap the root cause.
     */
    @Test
    public void test_throwAsIOE_withIOException() throws Exception {
        IOException ioException = new IOException("io error");

        try {
            sut.invokeThrowAsIOE(mockParser, ioException);
            Assert.fail("Expected JsonMappingException");
        } catch (Exception e) {
            Throwable actualException = (e instanceof java.lang.reflect.InvocationTargetException) ? e.getCause() : e;
            assertTrue(actualException instanceof JsonMappingException);
            assertEquals("io error", actualException.getMessage());
        }
    }

    /**
     * Tests that if the exception is a RuntimeException, ClassUtil.throwIfRTE 
     * will throw it directly without wrapping it in JsonMappingException.
     */
    @Test
    public void test_throwAsIOE_throwsRTEImmediately() throws Exception {
        RuntimeException rte = new RuntimeException("RTE");

        try {
            sut.invokeThrowAsIOE(mockParser, rte);
            Assert.fail("Expected RuntimeException to be thrown by ClassUtil");
        } catch (Exception e) {
            Throwable actualException = (e instanceof java.lang.reflect.InvocationTargetException) ? e.getCause() : e;
            assertEquals(rte, actualException);
        }
    }

